  ('c228', '청와대 앞길', '서울특별시 종로구 청운동 · 청운효자동 주민센터에서 청와대 앞을 지나 삼청동 주민센터로 이어지는 1.2km 코스(약 20분, 초급). 서울시 안내에 반려견 출입 가능(목줄 사용)으로 표시되어 있습니다. 현장 통제·행사에 따른 우회 여부를 확인해 주세요. 지도 핀은 청운효자동 주민센터 쪽 진입부 주변의 대표 위치입니다. 공식안내: https://gil.seoul.go.kr/trail/view.do?key=2405200007&sc_trailSeCd=SE001&sc_trailSn=158 · 확인일: 2026-10-01', 37.5847, 126.9705, null, array['공식안내','목줄필수','도심길'], '쉬움', '1.2 km', null, '서울시 서울, 테마산책길', 'approved', now()),
  ('c229', '춘천 강아지숲 산책 코스', '강원특별자치도 춘천시 남산면 충효로 437 · 아장·총총·성큼 등 반려견의 나이와 건강 상태에 따라 고를 수 있는 5~30분 산책 코스입니다. 한국관광공사 안내에 반려견 동반 입장과 산책줄·매너벨트 착용 조건이 명시되어 있습니다. 코스별 거리와 난이도는 별도 공개되지 않아 등록하지 않았습니다. 지도 핀은 시설 대표 위치이며 입장·운영 조건은 방문 전에 확인해 주세요. 공식안내: https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=d2061746-6134-4045-832e-ebe5382928ce · 확인일: 2026-10-01', 37.7365, 127.6620, null, array['공식안내','목줄필수','매너벨트필수'], null, null, null, '한국관광공사 반려동물 동반여행 안내', 'approved', now()),
  ('c230', '기흥레스피아 호수공원 C코스', '경기도 용인시 기흥구 · 조정경기장–기흥레스피아–생태학습장 일대 산책로 중 1.4km C코스(약 50분). 한국관광공사 반려동물 동반여행 안내는 호수공원 순환산책로와 반려견 놀이터를 소개합니다. 자전거·킥보드와 함께 쓰는 길이 있어 목줄을 짧게 잡고, 공원 출입 가능 구간을 방문 전에 확인해 주세요. 지도 핀은 호수공원 대표 위치이며 실제 경로는 공식 안내를 확인해 주세요. 공식안내: https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=e4fed9c7-93dc-47ad-938a-b4a5cb41e67e · 확인일: 2026-10-01', 37.2389, 127.1190, null, array['공식안내','목줄확인','호수길'], null, '1.4 km', null, '한국관광공사 반려동물 동반여행 안내', 'approved', now()),
  ('c231', '임실 오수의견관광지 반려견 산책로', '전북특별자치도 임실군 오수면 충효로 2096-16 · 관광지 안에 반려견 전용 놀이터와 산책로가 안내되어 있습니다. 한국관광공사 자료로 반려견 동반 관광지임을 확인했습니다. 산책로 거리와 난이도는 공개 자료에서 확인되지 않아 비워 두었습니다. 지도 핀은 관광지 대표 위치이며, 운영·이용 조건은 방문 전에 임실군에 확인해 주세요. 공식안내: https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=9465ddd2-7a16-42b4-8b21-03a6aea59eec · 확인일: 2026-10-01', 35.5452, 127.3327, null, array['공식안내','반려견전용 산책로'], null, null, null, '한국관광공사 반려동물 동반여행 안내', 'approved', now())
